def frequency_lists(lst):
    freq = {}
    for item in lst:
        if isinstance(item, list):
            for element in item:
                freq[element] = freq.get(element, 0) + 1
        else:
            freq[item] = freq.get(item, 0) + 1
    return freq

assert frequency_lists([[1, 2, 3, 2], [4, 5, 6, 2], [7, 8, 9, 5]])=={1: 1, 2: 3, 3: 1, 4: 1, 5: 2, 6: 1, 7: 1, 8: 1, 9: 1}
